mapper.select:
select A.DAYS termType,A.AMT sessionendBalance from( select t.days,sum(t.amt) amt from( select nvl(cmap.ASSETVALUE_A,0) amt,
case when info.mdate is null then '01' when info.mdate-#{endDate,jdbcType=DATE} >0 and info.mdate-#{endDate,jdbcType=DATE} <=1 then '01' when info.mdate-#{endDate,jdbcType=DATE} >1 and info.mdate-#{endDate,jdbcType=DATE} <=92 then '02' when info.mdate-#{endDate,jdbcType=DATE} >92 and info.mdate-#{endDate,jdbcType=DATE} <=184 then '03' when info.mdate-#{endDate,jdbcType=DATE} >184 and info.mdate-#{endDate,jdbcType=DATE} <=366 then '04' when info.mdate-#{endDate,jdbcType=DATE} >366 and info.mdate-#{endDate,jdbcType=DATE} <=1096 then '05' when info.mdate-#{endDate,jdbcType=DATE} >1096 and info.mdate-#{endDate,jdbcType=DATE} <=1827 then '06' when info.mdate-#{endDate,jdbcType=DATE} >1827 then '07' when info.perpetual_flag ='01' then '08' when info.mdate-#{endDate,jdbcType=DATE} <=0 then '09' end days
case when info.option_flag='01' then (case when exeplan.mdate is null then '01' when exeplan.mdate-#{endDate,jdbcType=DATE} >0 and exeplan.mdate-#{endDate,jdbcType=DATE} <=1 then '01' when exeplan.mdate-#{endDate,jdbcType=DATE} >1 and exeplan.mdate-#{endDate,jdbcType=DATE} <=92 then '02' when exeplan.mdate-#{endDate,jdbcType=DATE} >92 and exeplan.mdate-#{endDate,jdbcType=DATE} <=184 then '03' when exeplan.mdate-#{endDate,jdbcType=DATE} >184 and exeplan.mdate-#{endDate,jdbcType=DATE} <=366 then '04' when exeplan.mdate-#{endDate,jdbcType=DATE} >366 and exeplan.mdate-#{endDate,jdbcType=DATE} <=1096 then '05' when exeplan.mdate-#{endDate,jdbcType=DATE} >1096 and exeplan.mdate-#{endDate,jdbcType=DATE} <=1827 then '06' when exeplan.mdate-#{endDate,jdbcType=DATE} >1827 then '07' when info.perpetual_flag ='01' then '08' when exeplan.mdate-#{endDate,jdbcType=DATE} <=0 then '09' end ) else (case when info.mdate is null then '01' when info.mdate-#{endDate,jdbcType=DATE} >0 and info.mdate-#{endDate,jdbcType=DATE} <=1 then '01' when info.mdate-#{endDate,jdbcType=DATE} >1 and info.mdate-#{endDate,jdbcType=DATE} <=92 then '02' when info.mdate-#{endDate,jdbcType=DATE} >92 and info.mdate-#{endDate,jdbcType=DATE} <=184 then '03' when info.mdate-#{endDate,jdbcType=DATE} >184 and info.mdate-#{endDate,jdbcType=DATE} <=366 then '04' when info.mdate-#{endDate,jdbcType=DATE} >366 and info.mdate-#{endDate,jdbcType=DATE} <=1096 then '05' when info.mdate-#{endDate,jdbcType=DATE} >1096 and info.mdate-#{endDate,jdbcType=DATE} <=1827 then '06' when info.mdate-#{endDate,jdbcType=DATE} >1827 then '07' when info.perpetual_flag ='01' then '08' when info.mdate-#{endDate,jdbcType=DATE} <=0 then '09' end ) end days
from CHB_MONTH_ASSET_POSITION cmap left join(select cabd.mdate as mdate,cabd.asset_id from CHB_ASSETS_BASIS_DATA_NOBTM cabd WHERE 1=1 and cabd.value_date=#{endDate,jdbcType=DATE}
)exeplan on cmap.asset_code=exeplan.asset_id left join chb_asset_info info on cmap.asset_code=info.asset_code where 1=1 and cmap.ENDDATE=#{endDate,jdbcType=DATE} )t GROUP by t.DAYS ) A
ORDER by A.DAYS
